    contraindications: ['РђРєС‚РёРІРЅС‹Рµ РѕРїСѓС…РѕР»Рё', 'Р‘РµСЂРµРјРµРЅРЅРѕСЃС‚СЊ', 'Р’РѕР·СЂР°СЃС‚ <18 (РЅРµРґРѕСЃС‚Р°С‚РѕС‡РЅРѕ РґР°РЅРЅС‹С…)'],
