    risks: ['Р­РєСЃРїРµСЂРёРјРµРЅС‚Р°Р»СЊРЅС‹Р№ (РЅРµС‚ RCT РЅР° Р»СЋРґСЏС…)', 'РўРµРѕСЂРµС‚РёС‡РµСЃРєРёР№ СЂРёСЃРє РјРµС‚Р°СЃС‚Р°Р·РёСЂРѕРІР°РЅРёСЏ (Р°РєС‚РёРЅ-Р·Р°РІРёСЃРёРјС‹Р№)', 'Р‘РѕР»СЊ РїСЂРё РёРЅСЉРµРєС†РёРё'],
    contraindications: ['РђРєС‚РёРІРЅС‹Рµ РѕРїСѓС…РѕР»Рё', 'РњРµС‚Р°СЃС‚Р°Р·С‹', 'Р‘РµСЂРµРјРµРЅРЅРѕСЃС‚СЊ'],
